//! With the `tauri` feature, Tauri's plugin build writes the per-command permission files
//! (`permissions/autogenerated/`) and the schema, and hands them to the host app's build.

/// The plugin's commands (`plugin:sew-app|<name>`): the seventeen of `sew-app:default`, then
/// `handoff` (`sew-app:handoff` only), the five of `sew-app:transport`, and `upload_file`
/// (`sew-app:upload-file` only). Keep in step with `wire::COMMANDS`.
#[cfg(feature = "tauri")]
const COMMANDS: &[&str] = &[
    "servers",
    "add_server",
    "confirm_server",
    "remove_server",
    "server_info",
    "set_active",
    "sign_in",
    "pair",
    "sign_in_door",
    "sign_in_door_set_password",
    "pair_confirm",
    "pair_decline",
    "sign_out",
    "devices",
    "revoke_device",
    "open",
    "notify",
    "handoff",
    "api",
    "gateway_open",
    "gateway_send",
    "gateway_close",
    "upload_bytes",
    "upload_file",
];

fn main() {
    #[cfg(feature = "tauri")]
    tauri_plugin::Builder::new(COMMANDS).build();
}
